SELECT CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, CASE WHEN p.brand IN ('Acme', 'Umbrella') THEN 'core' ELSE 'other' END AS brand_group, MIN(ss.revenue) AS min_revenue, MIN(ss.units) AS min_units FROM store_sales ss JOIN products p ON p.id = ss.product_id LEFT JOIN stores s ON ss.store_id = s.id WHERE MONTH(p.launch_date) IN (1, 5, 9) GROUP BY CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END, CASE WHEN p.brand IN ('Acme', 'Umbrella') THEN 'core' ELSE 'other' END ORDER BY brand_group
